CREATE TABLE IF NOT EXISTS cloud_transfers (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, session_id VARCHAR(36) NOT NULL, from_member_id VARCHAR(36) NOT NULL, to_member_id VARCHAR(36) NOT NULL, initiator_id VARCHAR(36) NOT NULL, credential_id VARCHAR(36) NOT NULL, effective_member_id VARCHAR(36) NOT NULL, `state` VARCHAR(16) NOT NULL, resume BOOLEAN NOT NULL, force_pause BOOLEAN NOT NULL, pending_inputs VARCHAR(16) NOT NULL, version INT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, expires_at BIGINT NULL, decider_id VARCHAR(36) NULL, decider_credential_id VARCHAR(36) NULL, decider_effective_member_id VARCHAR(36) NULL, decided_at BIGINT NULL, completed_at BIGINT NULL, at_epoch INT NULL, event_seq BIGINT NULL, failure_code VARCHAR(64) NULL, failure_message VARCHAR(512) NULL, idempotency_key VARCHAR(128) COLLATE ascii_bin NULL, request_digest CHAR(64) NULL, CONSTRAINT cloud_transfers_team FOREIGN KEY (team_id) REFERENCES teams(id), CONSTRAINT cloud_transfers_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE);
ALTER TABLE cloud_transfers ADD CONSTRAINT cloud_transfer_idempotency UNIQUE (team_id, initiator_id, idempotency_key);
CREATE INDEX cloud_transfer_session ON cloud_transfers (session_id, `state`);
CREATE INDEX cloud_transfer_from ON cloud_transfers (team_id, from_member_id, created_at);
CREATE INDEX cloud_transfer_to ON cloud_transfers (team_id, to_member_id, created_at);
CREATE INDEX cloud_transfer_team ON cloud_transfers (team_id, created_at);
CREATE INDEX cloud_transfer_expiry ON cloud_transfers (`state`, expires_at);